window.MOTIF_CATALOG_CHUNKS[4]={"cards":[{"id":"MEJE-KW-000481","row_version":1,"title":"멸종한 지성 종족","original":"Extinct Sapient Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한때 언어·사회·기술을 가진 종족이 현재 시점에는 더 이상 살아 있지 않은 세계 설정. 기록과 유적이 후대 인물의 탐험이나 책임 문제를 남긴다. 사라질 위기의 종을 지키기는 아직 보호할 구성원이 남은 단계이며, 문명 흔적만 남은 행성은 장소 자체의 폐허를 다룬다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000481/index.html"},{"id":"MEJE-KW-000482","row_version":1,"title":"인간형이지만 인간식 언어와 사회가 없는 종족","original":"Feral Humanlike Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"몸 형태는 사람과 닮았지만 작품에서 인간식 언어와 도구 문화 없이 살아가는 종족. 외형만 보고 인간과 같은 생활 방식을 기대하는 인물의 오해를 드러낼 수 있다. 과거의 지성을 잃은 종족은 이전에는 복잡한 사회가 있었으나 그 능력이 사라진 경우다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000482/index.html"},{"id":"MEJE-KW-000483","row_version":1,"title":"과거의 지성을 잃은 종족","original":"Formerly Sapient Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"과거에는 언어와 복잡한 도구·사회가 있었지만 현재는 그 능력이나 생활 양식이 사라진 종족. 변화가 자연적·인위적·초자연적 과정 중 무엇인지에 따라 책임과 회복 가능성이 달라진다. 인간형이지만 인간식 언어와 사회가 없는 종족은 그런 과거를 전제하지 않는다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000483/index.html"},{"id":"MEJE-KW-000484","row_version":1,"title":"기술 수준이 앞선 외계 종족","original":"Higher-Tech Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"다른 사회보다 훨씬 앞선 기술을 보유해 교류·갈등에서 큰 영향력을 행사하는 외계 종족형. 기술 격차는 지식의 공유, 간섭, 오판을 둘러싼 긴장을 만든다. 인간이 우세하지 않은 세계에서는 인간을 밀어내는 힘이 기술일 수도 다른 조건일 수도 있다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000484/index.html"},{"id":"MEJE-KW-000485","row_version":1,"title":"인간에서 갈라진 가상 종족","original":"Human Subspecies","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"인간과 공통 조상을 갖거나 인간 집단에서 갈라져 별도 특징을 지니게 된 허구의 종족. 자연 변화·유전 공학·새 환경에 대한 장기 적응 등 기원은 작품이 정한다. 혼혈 자녀가 한쪽 종만 닮는 유전 규칙은 서로 다른 종 사이의 자녀에게 적용되는 별도 규칙이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000485/index.html"},{"id":"MEJE-KW-000486","row_version":1,"title":"인간이 우세하지 않은 세계","original":"Humans Are Not the Dominant Species","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인간이 존재하지만 정치·생태·기술의 주도권을 다른 종족이나 존재가 쥔 세계 설정. 인간이 보호받는 집단인지, 종속된 집단인지, 여러 세력 중 하나인지에 따라 이야기가 달라진다. 기술 수준이 앞선 외계 종족은 주도권을 바꾸는 한 가능한 원인이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000486/index.html"},{"id":"MEJE-KW-000487","row_version":1,"title":"이름만 그 동물인 캐릭터 디자인","original":"Informed Species","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"작품이 캐릭터를 특정 동물 종이라고 부르지만 외형만 보면 그 종을 알아보기 어려운 디자인 관습. 명칭과 시각 정보의 간극이 양식화나 제작상의 선택을 드러낸다. 더빙에서 동물의 종이 바뀌기나 각색에서 인물의 종이 바뀌기는 이름 또는 판본 자체가 바뀌는 경우다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000487/index.html"},{"id":"MEJE-KW-000488","row_version":1,"title":"서로 다른 종 사이의 입양 가족","original":"Interspecies Adoption","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00975"],"summary":"양육자와 자녀가 서로 다른 종에 속하지만 가족 관계를 맺고 함께 살아가는 설정. 생김새와 생활 방식의 차이가 돌봄의 방식이나 주변의 시선을 바꾼다. 서로 다른 종 사이의 우정은 가족이 아닌 동등한 친교를 다룬다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"입양 가족","entry_url":"cards/MEJE-KW-000488/index.html"},{"id":"MEJE-KW-000489","row_version":1,"title":"서로 다른 종 사이의 우정","original":"Interspecies Friendship","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00996"],"summary":"서로 다른 종에 속한 인물들이 신체와 문화의 차이를 지닌 채 친구가 되는 관계. 갈등이 있는 세계라면 개인 사이의 신뢰가 집단의 통념과 부딪힐 수 있다. 서로 다른 종 사이의 입양 가족은 양육 관계, 서로 다른 종 사이의 연애는 연인 관계에 초점을 둔다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"우정·동료","entry_url":"cards/MEJE-KW-000489/index.html"},{"id":"MEJE-KW-000490","row_version":1,"title":"서로 다른 종 사이의 연애","original":"Interspecies Romance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"종이 다른 두 인물이 연인 관계를 맺는 이야기 요소. 작품이 두 존재의 의사소통과 사회적 지위를 어떻게 설정했는지에 따라 관계의 장벽과 주변의 반응이 달라진다. 종을 같게 바꿔 이종 연애의 장벽을 없애기는 그 차이를 변신으로 처리하는 별도 전개다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000490/index.html"},{"id":"MEJE-KW-000491","row_version":2,"title":"외래 종 유입으로 무너지는 생태계","original":"Introduced Species Calamity","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"새로운 종이 한 지역에 들어온 뒤 기존 생물과 자원·먹이·서식 공간을 두고 충돌해 생태계가 흔들리는 세계 설정. 유입의 동기가 개척·실험·우연 중 무엇인지에 따라 책임 소재도 달라진다. 핵심 종의 제거가 불러온 생태 위기는 들어온 종이 아니라 사라진 종에서 문제가 시작된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-000491/index.html"},{"id":"MEJE-KW-000492","row_version":1,"title":"종족 전체에 타고난 마법 능력","original":"Mage Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"특정 종족의 구성원이 마법을 사용할 잠재력을 타고나는 세계의 능력 분배 규칙. 모두 같은 수준으로 마법을 쓰는지, 연습과 환경에 따라 차이가 나는지는 작품이 따로 정한다. 인간에서 갈라진 가상 종족은 그런 능력의 가능한 기원 중 하나다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000492/index.html"},{"id":"MEJE-KW-000493","row_version":1,"title":"마법 종족으로 변신하기","original":"Magical Species Transformation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 마법이나 초자연적 사건을 거쳐 이전과 다른 환상 종족의 신체와 능력을 얻는 변화. 새 소속을 받아들이는 과정이 정체성이나 인간관계의 전환점이 될 수 있다. 종족 전체에 타고난 마법 능력은 변신 사건보다 종족의 공통 능력에 관한 설정이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-000493/index.html"},{"id":"MEJE-KW-000494","row_version":1,"title":"다른 종을 닮은 의태 종족","original":"Mimic Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한 종의 집단이 다른 종의 겉모습이나 신호를 닮아 포식자를 피하거나 먹잇감에 접근하도록 설정된 존재 유형. 개별 인물이 잠시 변장하는 경우와 달리 닮은 형태가 그 종의 지속적인 특징이다. 이름만 그 동물인 캐릭터 디자인은 외형과 이름의 불일치가 핵심이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000494/index.html"},{"id":"MEJE-KW-000495","row_version":1,"title":"서로 다른 동물 종으로 꾸린 팀","original":"Mixed Animal Species Team","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"다른 동물 종의 인물들이 각자의 능력과 성격을 지닌 구성원으로 한 팀을 이루는 편성. 종의 차이가 역할 분담이나 시각적 구별을 돕지만 팀의 목적은 함께 정한다. 서로 다른 종 사이의 우정은 팀이라는 조직 형태를 필요로 하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000495/index.html"},{"id":"MEJE-KW-000496","row_version":1,"title":"종족의 통념을 거스르는 구성원","original":"My Species Doth Protest Too Much","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"작품이 한 종족에 부여한 공통 신념이나 행동 규칙을 그 종족의 구성원 한 명이 거부하는 전개. 구성원의 선택은 집단의 규범을 다시 보게 하거나 내부 갈등을 드러낸다. 동물 종의 고정 이미지를 뒤집는 캐릭터는 관객이 동물에게 기대하는 이미지가 뒤집히는 경우다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000496/index.html"},{"id":"MEJE-KW-000497","row_version":1,"title":"다른 종족에게서 받은 이름","original":"Name From Another Species","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 자신이 속하지 않은 종족의 말이나 명명 관습에서 이름을 얻은 설정. 누가 이름을 주었는지에 따라 입양·우정·문화 교류의 흔적이 드러난다. 외형과 성질을 그대로 딴 종족 이름은 개인의 이름보다 종족 전체를 부르는 방식이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000497/index.html"},{"id":"MEJE-KW-000498","row_version":1,"title":"다른 동물 종으로 대신 연기하기","original":"Portrayed by Different Species","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"영상 제작에서 이야기 속 동물 종을 실제 촬영 가능한 다른 종의 동물로 표현하는 선택. 관객이 보는 배우의 종과 작품이 말하는 등장 존재의 종이 달라진다. 각색에서 인물의 종이 바뀌기는 설정 자체를 바꾸는 경우이며, 이 카드는 설정을 유지한 채 표현 수단을 바꾼다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000498/index.html"},{"id":"MEJE-KW-000499","row_version":1,"title":"부모와 무관한 종으로 태어난 자녀","original":"Random Species Offspring","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"부모가 속한 종과 자녀의 종 사이에 작품이 설명하는 유전 관계가 보이지 않는 허구의 출생 규칙. 혈통보다 시각적 농담이나 상징을 우선한 세계에서 나타날 수 있다. 혼혈 자녀가 한쪽 종만 닮는 유전 규칙은 부모 가운데 한쪽의 종을 이어받는다는 점에서 다르다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000499/index.html"},{"id":"MEJE-KW-000500","row_version":1,"title":"종마다 사실성과 만화성이 다른 그림체","original":"Realistic Species, Cartoony Species","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"같은 작품 안에서 사람과 동물, 또는 서로 다른 동물 종을 각각 사실적인 그림체와 단순화된 그림체로 표현하는 시각 규칙. 종의 구별뿐 아니라 친숙함과 낯섦을 조절하는 연출이 된다. 이름만 그 동물인 캐릭터 디자인은 종의 식별과 외형이 어긋나는 다른 문제다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000500/index.html"},{"id":"MEJE-KW-000501","row_version":2,"title":"핵심 종의 제거가 불러온 생태 위기","original":"Removed Species Calamity","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"어떤 종이 사라지거나 크게 줄어든 뒤 그 종이 맡던 역할이 비어 다른 생물과 환경까지 연쇄적으로 흔들리는 세계 설정. 멸종을 막기 위한 선택과 이미 발생한 변화의 회복 문제가 이야기를 이끈다. 외래 종 유입으로 무너지는 생태계는 새로운 종의 등장으로 시작된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-000501/index.html"},{"id":"MEJE-KW-000502","row_version":1,"title":"반수생 동물이 선원으로 배치되기","original":"Semiaquatic Species Sailor","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"동물이 사회적 직업을 맡는 작품에서 물과 육지를 오가는 종을 배의 선원이나 선장으로 자주 배치하는 캐스팅 관습. 동물의 생활 환경을 직업 선택의 시각적 단서로 쓰는 방식이다. 서로 다른 동물 종으로 꾸린 팀은 직업 하나보다 팀 전체의 편성을 다룬다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000502/index.html"},{"id":"MEJE-KW-000503","row_version":1,"title":"종족별로 나뉜 국가","original":"Single-Species Nations","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"한 세계의 국가마다 특정 종족이 다수를 차지하거나 국가의 이름과 제도를 대표하는 정치 지형. 국경이 종족의 경계와 겹치면 소수 구성원의 위치와 종족 간 외교가 주요 쟁점이 된다. 한 행성이 하나의 문화로 환원되기는 국가보다 행성 전체를 단일 문화로 그리는 방식이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000503/index.html"},{"id":"MEJE-KW-000504","row_version":1,"title":"단 한 개체만 등장하는 종","original":"Single-Specimen Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"작품에 한 개체만 나타나고 같은 종의 다른 구성원이나 번식 과정이 설명되지 않는 존재 유형. 유일한 괴물이나 낯선 생물을 단독 사건으로 보여주며 세계의 생태적 빈칸을 남긴다. 멸종한 지성 종족은 과거에 여러 구성원이 있었음을 전제로 한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000504/index.html"},{"id":"MEJE-KW-000505","row_version":1,"title":"첩보를 특기로 설정한 종족","original":"Sneaky Spy Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한 종족이 정보 수집·잠입·교란에 뛰어나다는 평판을 가진 세계 설정. 능력이나 생존 전략이 첩보 역할로 이어질 수 있지만 구성원마다 선택과 숙련은 다르게 그릴 수 있다. 종족의 통념을 거스르는 구성원은 이런 집단 이미지에 반하는 개인을 드러낸다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000505/index.html"},{"id":"MEJE-KW-000506","row_version":1,"title":"동물 종마다 성별을 고정해 그리기","original":"Species Equals Gender","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"의인화 동물 작품에서 어떤 종의 인물을 특정 성별로만 또는 압도적으로 많이 등장시키는 캐릭터 구성 관습. 실제 종의 구성과 달리 외형이나 사회적 이미지가 성별 배치의 신호로 쓰인다. 동물 종의 고정 이미지를 뒤집는 캐릭터는 종에 붙은 기대 자체를 거스르는 경우다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000506/index.html"},{"id":"MEJE-KW-000507","row_version":1,"title":"종족마다 자기 대표 군주가 있기","original":"Species King","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"말하는 동물이나 환상 종족의 집단마다 그 구성원에게 권위를 인정받는 왕 또는 여왕을 두는 통치 설정. 군주의 권력이 종족 전체에 미치는지 한 지역에 한정되는지는 작품이 정한다. 종족별로 나뉜 국가는 군주 개인보다 정치 지형 전체를 다룬다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000507/index.html"},{"id":"MEJE-KW-000508","row_version":1,"title":"같은 종족에게 우선 충성하기","original":"Species Loyalty","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"여러 지성 종족이 함께 사는 세계에서 인물이 자기 종족의 생존이나 이익을 다른 관계보다 앞세우는 선택. 공동 위기에서는 연대를 만들 수 있고 다른 종족과의 관계에서는 갈등을 부를 수 있다. 종족의 통념을 거스르는 구성원은 집단 규범보다 개인의 판단을 택하는 경우다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000508/index.html"},{"id":"MEJE-KW-000509","row_version":1,"title":"동물 종의 고정 이미지를 뒤집는 캐릭터","original":"Species Subversives","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"관객이 특정 동물 종에 기대하는 성격이나 역할을 의도적으로 거스르는 캐릭터 구성. 예상과 다른 성향이 인물을 기억하게 하거나 종에 붙은 상투적 이미지를 드러낸다. 종족의 통념을 거스르는 구성원은 작품 안에서도 그 종의 집단 규범이 실제로 존재할 때의 내부 반발이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000509/index.html"},{"id":"MEJE-KW-000510","row_version":1,"title":"동물 종 이름을 성으로 쓰기","original":"Species Surname","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"말하는 동물 인물의 성이나 호칭에 그 인물의 동물 종 이름을 그대로 넣는 명명 관습. 가족 이름과 종 표시가 한 단어에 겹쳐 등장인물의 정체를 빠르게 알린다. 다른 종족에게서 받은 이름은 이름의 출처가 자기 종 밖에 있는 경우다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000510/index.html"},{"id":"MEJE-KW-000511","row_version":1,"title":"작품 제목에 종 이름을 앞세우기","original":"Species Title","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"이야기에서 중심이 되는 존재의 종 이름을 작품 제목으로 삼는 명명 방식. 주인공 한 명보다 그 종 전체나 집단을 이야기의 표지로 제시할 수 있다. 동물 종 이름을 성으로 쓰기는 작품 제목이 아닌 캐릭터의 이름에 종을 넣는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000511/index.html"},{"id":"MEJE-KW-000512","row_version":1,"title":"종족을 우월하게 그리기","original":"Superior Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한 종족을 다른 종족보다 능력·수명·사회적 성취에서 앞선 존재로 제시하는 세계 설정. 그 평가가 객관적인 작품 규칙인지 인물들의 자부심이나 선전인지 구별할 필요가 있다. 우월함을 지배 권리로 주장하는 종족은 비교 우위를 착취의 명분으로 삼는 별도 태도다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000512/index.html"},{"id":"MEJE-KW-000513","row_version":1,"title":"우월함을 지배 권리로 주장하는 종족","original":"The Right of a Superior Species","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"자신들이 더 강하거나 지능이 높다는 이유로 다른 지성 종족을 지배하거나 착취해도 된다고 믿는 세력의 논리. 작품은 그 주장을 권력의 정당화 방식으로 드러내거나 비판할 수 있다. 종족을 우월하게 그리기는 비교 설정 자체이며 지배 권리의 주장을 필수로 하지 않는다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000513/index.html"},{"id":"MEJE-KW-000514","row_version":1,"title":"관객이 동물 캐릭터의 종을 혼동하기","original":"Viewer Species Confusion","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"동물 캐릭터의 외형이나 명칭이 불분명해 관객이 작품이 정한 종과 다른 종으로 받아들이는 반응. 작품 속 인물의 오해인지 바깥 관객의 해석인지 구별해야 한다. 이름만 그 동물인 캐릭터 디자인은 이름과 묘사의 어긋남을 만든 표현 방식이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-000514/index.html"},{"id":"MEJE-KW-000515","row_version":1,"title":"집단 전체가 연민을 부르는 종족","original":"Woobie Species","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한 종족이 지속적인 박해·위기·손실을 겪도록 그려져 관객이나 이야기 속 인물의 보호 욕구를 이끄는 서사 배치. 종족 구성원 모두가 같은 성격을 지닌다는 뜻은 아니다. 사라질 위기의 종을 지키기는 실제 소멸 위협과 구출 행동에 초점을 둔다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000515/index.html"},{"id":"MEJE-KW-000516","row_version":1,"title":"작품 안에서 마법 규칙을 일관되게 지키기","original":"\"Magic A\" Is \"Magic A\"","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"작품이 정한 마법이나 초자연 능력의 조건과 한계를 이후 전개에서도 일관되게 적용하는 구성 원칙. 규칙을 자세히 설명했는지보다 앞서 보여 준 제약을 서사가 기억하는지가 중요하다. 종족 전체에 타고난 마법 능력처럼 능력의 소유 범위를 정했다면 그 범위의 예외도 이야기 안에서 설명해야 한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000516/index.html"},{"id":"MEJE-KW-000517","row_version":1,"title":"쓸수록 더 찾게 되는 마법","original":"Addictive Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법을 사용할 때의 만족감이나 의존 때문에 사용자가 자꾸 더 많은 마법을 쓰려 하는 능력 규칙. 반복 사용이 판단과 생활을 흔들 수 있으며, 힘의 대가가 별도로 붙을 수도 있다. 피를 대가로 쓰는 마법은 중독성보다 주문의 재료와 비용에 초점을 둔다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000517/index.html"},{"id":"MEJE-KW-000518","row_version":1,"title":"연금술을 마법처럼 운용하기","original":"Alchemy Is Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"재료의 배합과 조제에 초자연적 효과가 따라오는 세계의 연금술 설정. 제조 과정이 실험 절차처럼 보이더라도 결과와 작동 원리는 작품의 마법 규칙이 정한다. 계산식 자체가 주문이 되는 마법은 수식에 힘을 부여하는 다른 방식이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000518/index.html"},{"id":"MEJE-KW-000519","row_version":1,"title":"누구나 배울 수 있는 마법","original":"All-Accessible Magic","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01209","ML-T01210"],"summary":"태생적 자격 없이도 방법을 배우고 필요한 조건을 갖추면 누구나 마법을 시도할 수 있는 세계 규칙. 실제로 익힐 시간과 자원이 모두에게 같은지는 별도의 사회 문제다. 종족 전체에 타고난 마법 능력은 능력의 출발점을 종족의 선천적 특징에 둔다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"마법의 보편화","entry_url":"cards/MEJE-KW-000519/index.html"},{"id":"MEJE-KW-000520","row_version":1,"title":"마법을 무효화하는 힘","original":"Anti-Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법의 효과가 닿지 못하게 하거나 이미 있는 초자연적 힘을 사라지게 하는 능력. 적용 범위와 지속 시간이 정해지면 마법 사용자와의 대결에서 중요한 제한 조건이 된다. 걸린 마법의 효과를 해제하기는 이미 성립한 주문의 결과를 풀어내는 구체적인 경우다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000520/index.html"},{"id":"MEJE-KW-000521","row_version":1,"title":"마법 사용에 반대하는 세력","original":"Anti-Magical Faction","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"마법이나 초자연적 존재를 위험하거나 부당하다고 보고 사용을 막으려 조직적으로 행동하는 집단. 신념과 실제 목적이 다를 수도 있어 금지의 명분과 집행 방식을 따로 살핀다. 마법 사용 금지령은 세력의 존재보다 제도화된 규칙에 초점을 둔다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000521/index.html"},{"id":"MEJE-KW-000522","row_version":1,"title":"갑옷을 입으면 마법이 약해지기","original":"Armor and Magic Don't Mix","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"무거운 갑옷이나 특정 재질의 보호구가 주문 사용에 불리하다는 세계의 제약. 동작의 제한인지 마법 에너지와의 충돌인지 원인을 정하면 전투 역할도 달라진다. 집중을 유지해야 지속되는 마법은 장비보다 사용자의 정신적 부담을 제한 조건으로 삼는다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000522/index.html"},{"id":"MEJE-KW-000523","row_version":1,"title":"세계에 퍼진 배경 마력장","original":"Background Magic Field","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"공기나 지형처럼 세계 곳곳에 마력이 퍼져 있고 밀도에 따라 현상과 주문의 강도가 달라지는 설정. 인물은 그 힘을 끌어다 쓰거나 영향을 받으며, 마력이 약한 지역에서는 다른 규칙이 작동할 수 있다. 누구나 배울 수 있는 마법은 마력의 분포보다 사용 자격을 정한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000523/index.html"},{"id":"MEJE-KW-000524","row_version":1,"title":"마법 사용 금지령","original":"Ban on Magic","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"권력이나 공동체가 특정 장소·계층·종류의 마법 사용을 금지하는 사회 규칙. 제한 범위와 처벌, 예외를 누가 정하는지가 세계의 권력 구조를 드러낸다. 마법 사용에 반대하는 세력은 금지령을 만들거나 집행할 수 있는 집단이다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-000524/index.html"},{"id":"MEJE-KW-000525","row_version":1,"title":"공격 마법과 회복 마법의 역할 분담","original":"Black and White Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법 사용자의 역할을 적에게 피해를 주는 공격 계열과 아군을 보호·회복하는 지원 계열로 나누는 편성. 이름에 흑과 백이 쓰이더라도 선악의 판정과 반드시 같지는 않다. 악의 힘으로 취급되는 마법은 주문의 도덕적 평가와 금기에 관한 개념이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000525/index.html"},{"id":"MEJE-KW-000526","row_version":1,"title":"악의 힘으로 취급되는 마법","original":"Black Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"힘의 출처·발동 비용·결과 때문에 작품 안에서 위험하거나 금기시되는 마법. 누가 그것을 악하다고 부르는지와 실제 피해가 무엇인지를 구별하면 단순한 색깔 구분을 넘어선다. 공격 마법과 회복 마법의 역할 분담은 전투 기능의 구분이며 도덕적 판정과 별개다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000526/index.html"},{"id":"MEJE-KW-000527","row_version":1,"title":"어린 공격 마법사 캐릭터","original":"Black Magician Girl","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"전투에서 원거리 공격 주문을 맡고 젊고 활동적인 성격으로 그려지는 마법사 캐릭터형. 신체적 취약함과 큰 화력의 조합이 팀 안의 역할을 만든다. 공격 마법과 회복 마법의 역할 분담은 이런 인물을 배치하는 전투 체계이고, 어둠의 마법소녀 라이벌은 대립 역할이 핵심이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000527/index.html"},{"id":"MEJE-KW-000528","row_version":1,"title":"피를 대가로 쓰는 마법","original":"Blood Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"피의 제공이나 손실을 주문의 재료·조건·비용으로 삼는 마법 설정. 누가 피를 내는지와 동의 여부에 따라 같은 주문도 서로 다른 관계와 책임을 만든다. 악의 힘으로 취급되는 마법은 사회적 평가이고 피를 사용하는 모든 마법이 그 범주에 속할 필요는 없다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000528/index.html"},{"id":"MEJE-KW-000529","row_version":1,"title":"마법으로 태어난 존재","original":"Born of Magic","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"주문이나 소원 같은 초자연적 행위가 새로운 생명의 탄생 원인이 되는 세계 설정. 탄생 뒤에도 몸이 마력으로 이루어졌는지는 별도로 정할 수 있다. 마법 종족으로 변신하기는 이미 존재하던 인물의 종이 달라지는 사건이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000529/index.html"},{"id":"MEJE-KW-000530","row_version":1,"title":"평범한 말을 고유명사처럼 신비화하기","original":"Capital Letters Are Magic","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"평범한 단어를 세계 안의 특별한 힘이나 제도의 이름처럼 표기해 독자에게 의미의 무게를 알리는 언어 관습. 영어에서는 대문자 표기가, 한국어에서는 명칭의 반복·표기 구별·문맥이 비슷한 역할을 할 수 있다. 작품 안에서 마법 규칙을 일관되게 지키기는 명칭보다 작동 규칙의 일관성에 관한 원칙이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000530/index.html"},{"id":"MEJE-KW-000531","row_version":1,"title":"고양이에게 마법적 역할 주기","original":"Cats Are Magic","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01108","ML-T01109"],"summary":"고양이를 다른 동물보다 초자연적 현상에 민감하거나 마법을 다루는 존재로 배치하는 설정. 동료·안내자·변신의 형태 등 역할은 작품마다 다를 수 있다. 말하는 동물은 대화 능력에 초점을 두므로 마법 능력을 필수로 하지 않는다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"현실 동물","entry_url":"cards/MEJE-KW-000531/index.html"},{"id":"MEJE-KW-000532","row_version":1,"title":"진짜 마법사가 공연하는 서커스","original":"Circus of Magic","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"공연자들이 실제 초자연 능력을 무대의 묘기처럼 사용하거나 공연단을 은신처로 삼는 설정. 관객이 그것을 연출로 믿는지 진짜 마법으로 아는지에 따라 비밀의 성격이 달라진다. 마술 기술을 범죄에 쓰는 인물은 초자연 능력보다 무대 마술의 속임수를 활용한다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-000532/index.html"},{"id":"MEJE-KW-000533","row_version":1,"title":"전투·마법·책략으로 나뉜 세 사람","original":"Combat, Magic, Trickery Trio","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"세 명의 핵심 인물에게 직접 전투, 특수 능력, 잠입이나 협상 같은 책략을 각각 맡기는 팀 구성. 역할이 달라 같은 장애를 여러 방식으로 해결할 수 있다. 공격 마법과 회복 마법의 역할 분담은 마법 사용자 내부의 기능 구분이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000533/index.html"},{"id":"MEJE-KW-000534","row_version":1,"title":"집중을 유지해야 지속되는 마법","original":"Concentration-Bound Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"주문이 유지되는 동안 사용자가 계속 정신을 집중해야 하고 주의가 끊기면 효과도 약해지거나 사라지는 규칙. 방해와 피로가 힘의 자연스러운 약점이 된다. 갑옷을 입으면 마법이 약해지기는 장비를 통한 다른 제약이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000534/index.html"},{"id":"MEJE-KW-000535","row_version":1,"title":"마술 기술을 범죄에 쓰는 인물","original":"Criminal Magician","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"무대 마술의 손기술과 주의 분산을 절도·사기·도주 같은 범죄에 활용하는 인물형. 초자연적 주문 없이도 관객과 수사자의 시선을 속일 수 있다. 진짜 마법사가 공연하는 서커스는 실제 마법을 무대에 올린다는 점에서 다르다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000535/index.html"},{"id":"MEJE-KW-000536","row_version":1,"title":"어둠의 마법소녀 라이벌","original":"Dark Magical Girl","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"마법소녀 주인공과 닮은 힘을 지녔지만 처음에는 반대편에 서거나 위협적인 방식으로 그 힘을 쓰는 라이벌형. 대립의 원인이 충성·상처·오해 중 무엇인지에 따라 이후 관계가 달라진다. 어린 공격 마법사 캐릭터는 전투 역할과 나이의 이미지가 중심이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000536/index.html"},{"id":"MEJE-KW-000537","row_version":1,"title":"마법을 여러 학파로 나누기","original":"Disciplines of Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"한 세계의 마법을 효과와 훈련법이 다른 계열로 나누어 사용자와 기술의 전문 분야를 정하는 규칙. 한 사람이 여러 계열을 익힐 수 있는지와 계열 간 상성이 설정의 핵심이 된다. 공격 마법과 회복 마법의 역할 분담은 역할에 따른 한 가지 분류 방식이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000537/index.html"},{"id":"MEJE-KW-000538","row_version":1,"title":"걸린 마법의 효과를 해제하기","original":"Dispel Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"이미 발동해 대상이나 장소에 남아 있는 마법의 결과를 다른 힘으로 풀어내는 능력. 주문을 시작 전에 막는 방어와 달리 효과가 생긴 뒤 개입한다. 마법을 무효화하는 힘은 더 넓은 범위의 억제나 소거를 포함한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000538/index.html"},{"id":"MEJE-KW-000539","row_version":1,"title":"마법이 실재해도 싫어하는 인물","original":"Does Not Like Magic","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"마법이 눈앞에서 작동하는 세계에 살면서도 그것을 위험하거나 부당하다고 여겨 사용을 피하는 개인의 태도. 이유는 경험·신념·두려움 등으로 달라질 수 있다. 마법 사용에 반대하는 세력은 이런 입장이 조직적 행동으로 확장된 경우다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000539/index.html"},{"id":"MEJE-KW-000540","row_version":1,"title":"혼돈과 무질서를 다루는 마법","original":"Entropy and Chaos Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"주문의 효과를 불확실한 변화, 붕괴, 확률의 흔들림 같은 이미지로 표현하는 마법 계열. 작품은 그 힘의 난폭함과 실제 조종 가능 범위를 따로 정할 수 있다. 마법을 여러 학파로 나누기에서는 이러한 계열을 다른 마법과 구별해 배치한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000540/index.html"},{"id":"MEJE-KW-000541","row_version":1,"title":"낯선 문화의 표지를 마법사에게 몰아주기","original":"Ethnic Magician","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 주류로 삼은 문화 바깥의 옷차림·말투·의례를 마법사의 신비성 표지로 반복 사용하는 캐릭터 관습. 그 인물의 문화와 개인성을 충분히 그리는지, 외형만 빌려 낯섦을 소비하는지 살펴볼 필요가 있다. 어린 공격 마법사 캐릭터는 문화적 표지보다 전투 역할에 따른 유형이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000541/index.html"},{"id":"MEJE-KW-000542","row_version":1,"title":"실제 유물을 허구에서 마법 물건으로 만들기","original":"Famously Mundane, Fictionally Magical","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"현실에서 알려진 유물이나 물건에 작품 속에서만 초자연적 기원과 능력을 부여하는 변형. 원래의 역사적 존재와 허구 설정을 구별해야 이야기의 추가 해석이 선명해진다. 연금술을 마법처럼 운용하기는 물건의 실재 여부보다 제조 방식이 마법이 되는 경우다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000542/index.html"},{"id":"MEJE-KW-000543","row_version":1,"title":"계산식 자체가 주문이 되는 마법","original":"Formulaic Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"수학 기호나 계산식을 자연 현상을 설명하는 도구가 아니라 초자연적 효과를 일으키는 주문처럼 다루는 설정. 무엇을 계산해야 발동하는지 정하면 마법 사용자의 지식이 능력 조건이 된다. 연금술을 마법처럼 운용하기는 수식보다 재료의 조합과 조제를 중심으로 한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000543/index.html"},{"id":"MEJE-KW-000544","row_version":1,"title":"몸의 격투 동작으로 주문 쓰기","original":"Full-Contact Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"주문을 말이나 작은 손짓 대신 주먹질·회피·도약 같은 큰 전투 동작과 함께 발동하는 전투 방식. 마법과 근접전이 한 흐름으로 이어지지만 모든 격투가 마법일 필요는 없다. 집중을 유지해야 지속되는 마법은 몸의 움직임보다 정신적 유지 조건에 초점을 둔다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000544/index.html"},{"id":"MEJE-KW-000545","row_version":1,"title":"세계 안에서 실제로 작동하는 마법","original":"Functional Magic","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물의 믿음이나 무대 속임수만이 아니라 작품의 사건에 실제 효과를 내는 초자연적 기술로 마법을 설정하는 방식. 누가 쓸 수 있고 무엇을 할 수 있는지는 그다음에 정할 세부 규칙이다. 누구나 배울 수 있는 마법은 사용 자격을 넓게 둔 한 방식이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000545/index.html"},{"id":"MEJE-KW-000546","row_version":1,"title":"세대를 거듭하며 약해지는 마법 혈통","original":"Generational Magic Decline","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"마법 능력으로 알려진 가문이나 종족의 후대가 이전 세대보다 약한 힘을 지니게 되는 장기 변화. 원인이 유전·환경·세계의 변화 중 무엇인지에 따라 후손의 선택과 사회적 지위가 달라진다. 종족 전체에 타고난 마법 능력은 종족의 잠재력 배분에 관한 기본 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000546/index.html"},{"id":"MEJE-KW-000547","row_version":1,"title":"도형과 마법진으로 주문 발동하기","original":"Geometric Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"정해진 선과 도형을 그려야 주문이 성립하는 마법 규칙. 모양의 정확도와 설치 위치가 주문의 조건이 되어 준비 과정 자체가 사건이 된다. 상징과 의식을 엮는 헤르메스식 마법은 도형을 포함한 더 넓은 의례 체계다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000547/index.html"},{"id":"MEJE-KW-000548","row_version":1,"title":"고딕풍 소녀에게 마법 능력 주기","original":"Goth Girls Know Magic","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"어두운 옷차림과 고딕풍 취향을 지닌 소녀 인물에게 초자연 능력을 함께 부여하는 캐릭터 관습. 외형의 분위기가 능력에 대한 관객의 기대를 만드는 연출이다. 어둠의 마법소녀 라이벌은 주인공과의 대립 관계가 중심이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000548/index.html"},{"id":"MEJE-KW-000549","row_version":1,"title":"치유에 가장 많은 힘이 드는 마법","original":"Healing Magic Is the Hardest","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"공격이나 이동 주문보다 상처의 회복에 더 높은 능력과 비용을 요구하는 세계 규칙. 치료가 어렵기 때문에 부상의 위험과 회복을 위한 선택이 이야기에서 무게를 얻는다. 신성한 힘이 상처를 회복시키기는 힘의 출처를 신성함에 둔 치유 방식이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000549/index.html"},{"id":"MEJE-KW-000550","row_version":1,"title":"상징과 의식을 엮는 헤르메스식 마법","original":"Hermetic Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"기호·말·재료·의례를 대응 관계로 묶어 효과를 내는 서양 신비주의풍 마법의 묘사. 작품은 실제 전통의 요소를 변형해 독자적인 주문 체계로 재구성할 수 있다. 도형과 마법진으로 주문 발동하기는 그중 도형을 핵심 조건으로 삼는 경우다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000550/index.html"},{"id":"MEJE-KW-000551","row_version":1,"title":"신성한 힘이 상처를 회복시키기","original":"Holy Healing Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"신성함과 연결된 힘이 인물의 상처나 해로운 상태를 회복시키는 허구의 치유 방식. 특정 신의 직접 허락이 필요한지, 신성한 성질만으로 가능한지는 작품이 정한다. 치유에 가장 많은 힘이 드는 마법은 회복의 출처보다 난도를 다룬다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000551/index.html"},{"id":"MEJE-KW-000552","row_version":1,"title":"물과 얼음 마법을 같은 속성으로 묶기","original":"Ice Magic Is Water","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"물과 얼음을 하나의 마법 속성으로 취급해 같은 사용자가 두 형태를 다루게 하는 분류 규칙. 게임에서는 기술의 상성과 저항을 정할 때에도 하나의 속성으로 계산할 수 있다. 용암을 불 마법의 상위 형태로 쓰기는 다른 원소 경계를 합치는 방식이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000552/index.html"},{"id":"MEJE-KW-000553","row_version":1,"title":"현실에서 불가능한 수준의 무대 마술","original":"Impossibly Awesome Magic Trick","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품은 초자연 능력이 없다고 설명하면서도 무대 마술사가 현실적 준비만으로는 불가능해 보이는 묘기를 성공시키는 연출. 관객이 속임수의 원리를 묻기보다 놀라움을 받아들이도록 구성한다. 마술 기술을 범죄에 쓰는 인물은 그런 기술을 범행에 이용하는 인물형이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000553/index.html"},{"id":"MEJE-KW-000554","row_version":1,"title":"우아한 여성 공격 마법사","original":"Lady of Black Magic","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"차분하고 우아한 인상으로 강력한 원거리 공격 주문을 맡는 여성 마법사 캐릭터형. 전투 역할은 어린 공격 마법사 캐릭터와 겹칠 수 있으나 나이와 성격, 화면에서의 표현 방식이 다르다. 이름의 흑마법은 반드시 악의 힘으로 취급되는 마법을 뜻하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-000554/index.html"},{"id":"MEJE-KW-000555","row_version":1,"title":"특정 언어로만 발동하는 주문","original":"Language of Magic","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"일상 언어와 달리 특정 말이나 언어 체계로 표현해야 주문이 작동하는 규칙. 언어를 누가 알고 배울 수 있는지가 마법의 접근성과 권력에 영향을 준다. 라틴어를 마법 언어로 쓰기는 실제 언어의 이미지를 빌리는 한 가지 표현이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000555/index.html"},{"id":"MEJE-KW-000556","row_version":1,"title":"게임 후반에 얻는 압도적 주문","original":"Last Disc Magic","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 막바지에 배우거나 얻는 주문이 이전의 공격 수단보다 훨씬 강해지는 보상 구조. 입수 시점과 사용 비용을 조절해 후반 전투의 역할을 만든다. 공격 마법과 회복 마법의 역할 분담은 기술의 획득 시기보다 파티 안의 기능을 나눈다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-000556/index.html"},{"id":"MEJE-KW-000557","row_version":1,"title":"라틴어를 마법 언어로 쓰기","original":"Latin Is Magic","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"주문이나 금기의 언어에 라틴어 또는 라틴어처럼 들리는 표현을 써서 오래된 지식의 인상을 주는 관습. 작품 안에서 실제로 그 말이 힘을 발동시키는지, 분위기만 만드는지는 별개의 선택이다. 특정 언어로만 발동하는 주문은 발동 조건 자체를 정한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000557/index.html"},{"id":"MEJE-KW-000558","row_version":1,"title":"용암을 불 마법의 상위 형태로 쓰기","original":"Lava Magic Is Fire","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"용암 공격을 불 속성 마법의 강한 단계로 분류하는 작품의 원소 체계. 용암을 땅과 불의 결합으로 볼 수도 있어 분류 선택이 기술 상성을 바꾼다. 물과 얼음 마법을 같은 속성으로 묶기도 가까운 현상을 하나의 마법 계열로 합친다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000558/index.html"},{"id":"MEJE-KW-000559","row_version":1,"title":"사용 횟수가 정해진 마법 도구","original":"Limited-Use Magical Device","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"주문이나 효과를 미리 담아 두었다가 정해진 횟수만 사용할 수 있는 물건. 사용 가능 횟수가 줄어들수록 언제 효과를 꺼낼지 선택이 중요해진다. 원하는 대상을 가리키는 나침반은 길 안내 기능 자체가 중심인 마법 도구다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000559/index.html"},{"id":"MEJE-KW-000560","row_version":1,"title":"현실의 문학 작품에 마법적 기원 주기","original":"Literary Work of Magic","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"현실에 알려진 문학 작품이 허구 세계에서는 의식·암호·초자연적 목적 때문에 쓰였다고 재해석하는 변형. 실제 작품의 성립 과정과 소설 속 설정을 구별해야 한다. 실제 유물을 허구에서 마법 물건으로 만들기는 문학 작품 바깥의 실재 물건까지 포함한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-000560/index.html"},{"id":"MEJE-KW-000561","row_version":1,"title":"사랑을 강제한 마법의 후유증","original":"Love Magic's Bitter Aftertaste","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"상대의 선택을 바꾸는 마법으로 연애 감정을 얻으려 한 뒤 관계와 인물의 자율성에 해로운 결과가 남는 전개. 마법의 성공 여부보다 강제로 만든 친밀감이 남기는 손상을 살핀다. 마법 계약에서 시작되는 연애는 계약 관계가 사랑으로 변하는 별도 구조다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000561/index.html"},{"id":"MEJE-KW-000562","row_version":1,"title":"마력 자체로 이루어진 존재와 사물","original":"Made of Magic","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"생명체나 물건의 재료 자체가 마력이며 그 힘이 사라지면 형태나 존재도 흔들리는 설정. 어떻게 만들어졌는지와 현재 무엇으로 이루어졌는지는 구별해야 한다. 마법으로 태어난 존재는 탄생의 원인이 마법이지만 몸의 재료까지 마력일 필요는 없다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000562/index.html"},{"id":"MEJE-KW-000563","row_version":1,"title":"질문에 답하는 점괘 도구","original":"Magic 8-Ball","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"사용자가 질문을 던지면 짧은 답이나 예언을 돌려주는 물리적 도구. 답이 실제 미래를 가리키는지 우연한 문구인지는 작품이 정한다. 원하는 대상을 가리키는 나침반은 질문에 말로 답하는 대신 방향을 알려 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000563/index.html"},{"id":"MEJE-KW-000564","row_version":1,"title":"한 번에 낫게 하는 만능 해독제","original":"Magic Antidote","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"독이나 질병의 영향을 극적인 한 번의 복용이나 처치로 빠르게 없애는 허구의 치료 물건. 제한 시간과 입수 난도가 구출 서사의 긴장을 만들 수 있다. 치유에 가장 많은 힘이 드는 마법은 회복의 난도를 주문 체계 안에서 정한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000564/index.html"},{"id":"MEJE-KW-000565","row_version":1,"title":"브레이크 고장만으로 차가 폭주하기","original":"Magic Brakes","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"차량의 브레이크가 고장 나면 다른 감속 방법이 모두 사라진 듯 차가 계속 빨라지는 추격 장면의 과장. 제목의 Magic은 실제 마법이 아니라 위험을 극대화하는 연출을 가리킨다. 낡은 저장매체에 터무니없는 기능 주기도 평범한 기술 물건의 능력을 과장한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000565/index.html"},{"id":"MEJE-KW-000566","row_version":1,"title":"초자연적 능력을 얻은 평범한 차량","original":"Magic Bus","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"겉으로는 흔한 차량처럼 보이지만 정상적인 차량의 범위를 넘어서는 이동·변형·판단 능력을 지닌 탈것. 그 능력이 개조 기술인지 작품 속 초자연성인지 구분하는 것이 핵심이다. 승객을 태워 나는 양탄자는 처음부터 마법 탈것으로 제시되는 물건이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000566/index.html"},{"id":"MEJE-KW-000567","row_version":1,"title":"마법을 다른 이름으로 부르기","original":"Magic by Any Other Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"마법처럼 작동하는 힘을 세계 안의 인물들이 과학·기술·정신 능력 등 다른 이름으로 부르는 명명 방식. 그 이름이 믿음의 차이인지 실제 원리의 차이인지 작품이 정한다. 기술을 마법으로 오해하기는 반대로 기술의 효과를 마법이라고 받아들이는 경우다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-000567/index.html"},{"id":"MEJE-KW-000568","row_version":1,"title":"승객을 태워 나는 양탄자","original":"Magic Carpet","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"승객이 올라타면 하늘이나 다른 공간으로 이동할 수 있는 마법 양탄자. 이동 수단인 동시에 세계의 마법이 일상 물건에 스며든 모습을 보여 준다. 초자연적 능력을 얻은 평범한 차량은 양탄자 대신 차량의 형태를 유지한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000568/index.html"},{"id":"MEJE-KW-000569","row_version":1,"title":"마법을 끓이는 가마솥","original":"Magic Cauldron","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"약재나 신비한 재료를 넣어 주문의 결과물을 만드는 솥, 또는 솥 자체에 초자연 능력이 깃든 물건. 도구가 마법을 쓰는지 단순히 조리 용기인지 설정마다 다르다. 연금술을 마법처럼 운용하기는 솥을 포함할 수 있는 제조 체계다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000569/index.html"},{"id":"MEJE-KW-000570","row_version":1,"title":"원하는 대상을 가리키는 나침반","original":"Magic Compass","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"북쪽 대신 사람·물건·장소 같은 목표를 향하는 방향을 알려 주는 초자연적 도구. 어떤 질문을 받을 수 있고 목표가 움직일 때 어떻게 반응하는지가 탐색 규칙이 된다. 질문에 답하는 점괘 도구는 방향보다 말이나 짧은 예언을 돌려준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-000570/index.html"},{"id":"MEJE-KW-000571","row_version":1,"title":"마법 계약에서 시작되는 연애","original":"Magic Contract Romance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"마법으로 묶인 계약 당사자들이 함께 행동하는 과정에서 연인 관계로 발전하는 서사. 계약의 의무와 스스로 선택한 애정이 얼마나 다른지가 관계의 긴장을 만든다. 사랑을 강제한 마법의 후유증은 감정 자체를 강제로 바꾼 경우다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-000571/index.html"},{"id":"MEJE-KW-000572","row_version":1,"title":"긴장에 맞춰 늘어나는 초읽기","original":"Magic Countdown","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"화면에 제시된 남은 시간이 실제 장면의 경과보다 느리거나 빠르게 흘러 극적 위기를 맞추는 연출 관습. 제목의 Magic은 초자연 능력이 아니라 초읽기의 편의적인 변화에 붙은 표현이다. 게임 후반에 얻는 압도적 주문과 달리 마법 체계의 규칙을 말하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-000572/index.html"},{"id":"MEJE-KW-000573","row_version":1,"title":"춤 동작으로 발동하는 마법","original":"Magic Dance","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"정해진 동작과 리듬을 수행해야 주문이 작동하는 능력 규칙. 동작을 잃거나 흐름이 끊기면 주문도 실패할 수 있어 몸의 숙련이 마법의 조건이 된다. 몸의 격투 동작으로 주문 쓰기는 춤의 리듬보다 전투 동작을 중심으로 한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000573/index.html"},{"id":"MEJE-KW-000574","row_version":1,"title":"마력을 먹는 존재","original":"Magic Eater","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"마력이나 주문의 효과를 먹이로 삼는 존재 유형. 먹는 행위가 주변의 주문을 소거하거나 자신의 힘을 키우는 규칙으로 이어질 수 있다. 마법을 무효화하는 힘은 먹이를 필요로 하지 않는 더 넓은 소거 능력이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-000574/index.html"},{"id":"MEJE-KW-000575","row_version":1,"title":"원래 능력을 마법으로 증폭하기","original":"Magic Enhancement","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이나 물건이 이미 가진 힘·감각·내구성을 마법으로 더 강하게 만드는 효과. 전혀 없던 능력을 새로 부여하는 주문과 구별하면 증폭의 범위가 선명해진다. 사용 횟수가 정해진 마법 도구는 강화 효과를 제한된 횟수로 담아 둘 수 있는 물건이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000575/index.html"},{"id":"MEJE-KW-000576","row_version":1,"title":"가짜 마법 물건에 의지해 능력을 쓰기","original":"Magic Feather","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 평범한 물건에 힘이 있다고 믿어 자신의 능력을 발휘하다가 나중에 물건의 효력이 없었음을 알게 되는 전개. 믿음과 자신감이 실제 역량을 가린 이유가 밝혀진다. 사용 횟수가 정해진 마법 도구는 물건에 실제 주문이 담긴 경우다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-000576/index.html"},{"id":"MEJE-KW-000577","row_version":1,"title":"일반 불과 다른 성질의 마법 불","original":"Magic Fire","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"연료·열·색·소멸 조건이 보통의 불과 다르게 작동하는 초자연적 불. 단지 주문으로 불을 켰다는 사실보다 불 자체의 특수한 성질이 핵심이다. 용암을 불 마법의 상위 형태로 쓰기는 원소 분류의 문제다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-000577/index.html"},{"id":"MEJE-KW-000578","row_version":1,"title":"낡은 저장매체에 터무니없는 기능 주기","original":"Magic Floppy Disk","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"시대가 지난 저장매체가 작품에서 보통의 용량과 속도를 훨씬 넘는 데이터 도구로 쓰이는 제작 관습. 익숙한 소품을 화면에 보여 주려는 선택과 이야기 속 기능 사이에 간극이 생긴다. 브레이크 고장만으로 차가 폭주하기도 기술 물건의 실제 역할을 극적으로 단순화한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-000578/index.html"},{"id":"MEJE-KW-000579","row_version":1,"title":"작품의 한 단어가 팬덤의 암호가 되기","original":"Magic Franchise Word","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작품에서 유난히 기억에 남는 한 단어를 팬들이 반복해 쓰면서 작품을 알아보는 신호로 삼는 현상. 원래 일상어였더라도 팬덤 안에서는 맥락을 부르는 짧은 표지가 된다. 평범한 말을 고유명사처럼 신비화하기는 작품 내부의 명명 방식이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-000579/index.html"},{"id":"MEJE-KW-000580","row_version":1,"title":"기술을 마법으로 오해하기","original":"Magic from Technology","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품의 실제 원리는 기술인데 관찰자가 그 작동 방식을 몰라 마법처럼 받아들이는 세계 설정. 사용자와 주변 인물의 지식 차이가 신비감이나 권력의 차이를 만든다. 마법을 다른 이름으로 부르기는 마법 같은 힘에 다른 이름을 붙이는 반대 방향의 명명이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-000580/index.html"}]}.cards;